# Occupational classification uses source occupation names, not ambiguous aliases.
rules=[(2,'machine learning|artificial intelligence'),(4,'security.*(computer|information)|information security'),(5,'network|cloud|systems administrator'),(3,'data scien|statistic|data anal'),(1,'software|programmer|web developer|software quality'),(6,'human resources|recruit|training and development|labor relations'),(7,'accountant|auditor|bookkeep|tax prepar'),(8,'financial|investment|bank|credit|securities'),(10,'management analyst|risk'),(11,'sales|business development'),(12,'marketing|advertis|market research|public relations|content|seo'),(14,'nurs|pharmac'),(13,'physician|surgeon|medical|dent|therap|health|optomet|chiropr|paramedic'),(15,'engineer|architect|drafter|surveyor'),(16,'teacher|professor|education|librarian|instruction|research assistant'),(17,'lawyer|legal|judicial|judge|paralegal|compliance'),(19,'logistic|supply chain|warehouse|shipping|purchasing|buyer|cargo|freight'),(20,'customer service|customer support|customer success'),(21,'design|artist|animator|photograph'),(22,'editor|writer|journalist|media|actor|musician|dancer|producer|broadcast'),(23,'hotel|lodging|tour|chef|cook|restaurant|food service|travel'),(24,'retail|store|cashier|e-commerce'),(27,'government|legislat|public administration|police|firefight|detective|correction'),(28,'scientist|biolog|chemist|physic|biotech|laboratory|microbiol'),(29,'agricultur|farm|forest|environment|conservation|animal|fish|landscap'),(30,'pilot|aviation|transport|driver|air traffic|rail|sailor|flight'),(31,'insurance|actuar'),(32,'telecom'),(33,'social work|social service|counsel|nonprofit|community service|religious|clergy'),(26,'construction|real estate|carpenter|plumber|electrician|roof|mason|building|property'),(25,'manufactur|production|machin|assembler|welder|fabricat|metal|mechanic|repair|operator'),(0,'computer|information technology|it administrator'),(18,'administrat|office|secretar|clerks|reception|assistant'),(9,'manager|executive|director|chief|president')]
category_names={0:['IT services','Systems and support'],1:['Application development','Software quality'],2:['Intelligent systems','Applied AI'],3:['Analytics','Data research'],4:['Information security','Security operations'],5:['Cloud infrastructure','Networks'],6:['People operations','Talent acquisition'],7:['Accounting','Audit and taxation'],8:['Financial services','Investment'],9:['Leadership','Business operations'],10:['Advisory','Business analysis'],11:['Sales','Account management'],12:['Digital marketing','Communications'],13:['Clinical practice','Allied healthcare'],14:['Nursing','Pharmacy'],15:['Engineering','Architecture'],16:['Teaching','Research'],17:['Legal practice','Compliance'],18:['Administration','Office support'],19:['Logistics','Procurement'],20:['Customer support','Customer success'],21:['Creative practice','Design'],22:['Editorial','Performing arts'],23:['Hospitality','Travel'],24:['Retail operations','Online commerce'],25:['Production','Maintenance'],26:['Construction trades','Property'],27:['Public services','Administration'],28:['Laboratory science','Life sciences'],29:['Agriculture','Environmental practice'],30:['Transport operations','Aviation'],31:['Insurance services','Actuarial practice'],32:['Communications networks','Technical services'],33:['Community services','Social care'],34:['Professional services','Emerging occupations']}
def classify(title):
 for i,pattern in rules:
  if re.search(pattern,title,re.I):return i
 return 34
families={i:('clinical' if i in [13,14] else 'research' if i in [16,28] else 'technical' if i in [0,1,2,3,4,5,15,32] else 'creative' if i in [12,21,22] else 'advisory' if i in [7,8,10,17,31] else 'operations' if i in [19,23,24,25,26,29,30] else 'business') for i in range(len(industries))}
orders={'clinical':['summary','certifications','experience','education','skills','projects','achievements','additional'],'research':['summary','education','experience','publications','projects','skills','certifications','achievements','additional'],'technical':['summary','skills','experience','projects','education','certifications','achievements','additional'],'creative':['summary','projects','experience','skills','education','certifications','achievements','additional'],'advisory':['summary','experience','certifications','skills','education','projects','achievements','additional'],'operations':['summary','experience','skills','certifications','education','projects','achievements','additional'],'business':['summary','experience','skills','education','projects','certifications','achievements','additional']}
guidance={'clinical':['Describe your clinical setting, patient-care scope and actual practice areas.','Include only licences and certifications you hold; include issuer and validity dates.'],'research':['Describe your research interests, methods and actual contributions.','Include publications and presentations with their true authorship and links.'],'technical':['Describe the systems and technical problems you have actually worked on.','Organise real tools and skills; use projects to show applied work.'],'creative':['Describe your creative discipline, audience and portfolio focus.','Use selected campaigns or portfolio projects with links and real contributions.'],'advisory':['Describe your advisory domain and the engagements you actually contributed to.','Keep confidential client details private; include only held credentials.'],'operations':['Describe your operational setting, responsibilities and safety practices.','Mention tools, licences and processes only where supported by your experience.'],'business':['Describe your area of responsibility and professional strengths.','Show actual team, client or business contributions without invented results.']}
data={ 'resume_catalogue_sources':[{'id':'onet-31','label':'O*NET occupation names','version':'31.0','source_url':'https://www.onetcenter.org/database.html','license':'CC BY 4.0','attribution':'O*NET 31.0 Database, U.S. Department of Labor, Employment and Training Administration. O*NET is a trademark of USDOL/ETA.','modifications':'Hirely classified occupation names, normalized titles, selected aliases, and added professional structures; not endorsed by USDOL/ETA.'},{'id':'hirely','label':'Hirely title additions','version':'1','source_url':'https://hirely-advantage-platform.lovable.app','license':'Hirely editorial additions','attribution':'Hirely','modifications':'Indian and emerging role names.'}], 'resume_industries':[{'id':slug(v),'label':v,'sort_order':i} for i,v in enumerate(industries)],'resume_categories':[], 'resume_role_blueprints':[],'resume_occupations':[],'resume_occupation_categories':[],'resume_job_titles':[],'resume_title_aliases':[],'resume_career_levels':[{'id':slug(v),'label':v,'sort_order':i} for i,v in enumerate(levels)],'resume_occupation_levels':[],'resume_template_designs':[],'resume_template_assignments':[]}
for i,v in enumerate(industries):
 for c in category_names[i]: data['resume_categories'].append({'id':slug(v)+'-'+slug(c),'industry_id':slug(v),'label':c})
for f,order in orders.items(): data['resume_role_blueprints'].append({'id':f,'label':f.title()+' professional','definition':{'order':order,'guidance':guidance[f],'summaryPrompt':guidance[f][0]}})
for key,label,font,spacing in [('classic','Classic','Times','normal'),('editorial','Editorial','Georgia','relaxed'),('modern','Modern','Arial','normal')]:data['resume_template_designs'].append({'id':key,'label':label,'renderer_key':key,'definition':{'fontFamily':font,'fontSize':11,'spacing':spacing,'accent':'#111827','headerAlign':'center' if key=='editorial' else 'left','headingRule':key!='modern'}})
occs=pd.read_excel(root/'occupations.xlsx'); title_rows=pd.read_excel(root/'titles.xlsx'); reported=pd.read_excel(root/'reported.xlsx'); lookup={}; seen={};
for _,o in occs.iterrows():
 code=o['O*NET-SOC Code']; title=o['Title']; i=classify(title); industry=slug(industries[i]); category=industry+'-'+slug(category_names[i][0]); oid='onet-'+code; f=families[i]; lookup[code]=(oid,industry,category)
 data['resume_occupations'].append({'id':oid,'title':title,'source_id':'onet-31','source_code':code,'blueprint_id':f})
 data['resume_occupation_categories'].append({'occupation_id':oid,'category_id':category})
 if code.startswith('11-1011'): allowed=['Executive Director','Chief Executive / C-Suite','President','Founder / CEO']
 elif code.startswith('11-'):allowed=['Assistant Manager','Manager','Senior Manager','Department Head','Director','Senior Director','Vice President','Senior Vice President']
 elif i in [13,14]: allowed=['Student','Internship','Graduate','Entry-Level','Junior','Experienced','Senior','Specialist','Senior Specialist','Supervisor']
 elif i in [25,26,29,30]:allowed=['Student','Internship','Entry-Level','Junior','Experienced','Senior','Specialist','Team Lead','Supervisor']
 else:allowed=['Student','Internship','Graduate','Fresher','Entry-Level','Junior','Associate','Mid-Level','Experienced','Senior','Specialist','Senior Specialist','Team Lead','Supervisor']
 for l in allowed:
  lid=slug(l);data['resume_occupation_levels'].append({'occupation_id':oid,'level_id':lid})
  for design in ['classic','editorial','modern']:data['resume_template_assignments'].append({'id':oid+'-'+lid+'-'+design,'occupation_id':oid,'level_id':lid,'blueprint_id':f,'design_id':design})
def add_title(title,code,rank=None):
 normalized=' '.join(str(title).lower().split())
 if normalized in seen:return seen[normalized]
 if code not in lookup:return None
 oid,industry,category=lookup[code];tid=hashlib.sha256(normalized.encode()).hexdigest()[:24];seen[normalized]=tid
 data['resume_job_titles'].append({'id':tid,'occupation_id':oid,'title':str(title).strip(),'normalized_title':normalized,'industry_id':industry,'category_id':category,'popular_rank':rank});return tid
for _,o in occs.iterrows():add_title(o['Title'],o['O*NET-SOC Code'])
examples={'Senior HR Manager':'11-3121.00','HR Executive':'13-1071.00','Talent Acquisition Specialist':'13-1071.00','Senior Recruiter':'13-1071.00','Data Analyst':'15-2051.00','Senior Data Scientist':'15-2051.00','Machine Learning Engineer':'15-2051.00','Software Engineer':'15-1252.00','Principal Software Engineer':'15-1252.00','IT Administrator':'15-1244.00','Cybersecurity Analyst':'15-1212.00','Financial Analyst':'13-2051.00','Chartered Accountant':'13-2011.00','Risk Advisory Consultant':'13-1111.00','Business Analyst':'13-1111.00','Senior Management Consultant':'13-1111.00','Digital Content Lead':'27-3043.00','SEO Specialist':'13-1161.00','Customer Insights Manager':'11-2021.00','Senior Account Executive':'41-3091.00','Director of Sales':'11-2022.00','Customer Support Team Lead':'43-1011.00','Store Manager':'41-1011.00','Product Line Manager':'11-2021.00','Operations Director':'11-1021.00'}
for rank,(t,c) in enumerate(examples.items()):add_title(t,c,rank)
for _,row in title_rows.iterrows():add_title(row['Job Title'],row['O*NET-SOC Code'])
for _,row in reported.iterrows():
 tid=add_title(row['Reported Job Title'],row['O*NET-SOC Code'])
 if tid and '(' in row['Reported Job Title']:
  alias=row['Reported Job Title'].split('(')[0].strip();data['resume_title_aliases'].append({'title_id':tid,'alias':alias,'normalized_alias':alias.lower()})
# Searchable abbreviations are editorial aliases; they never become personal skills.
for title,aliases in {'Software Engineer':['SWE','Software Developer'],'Human Resources Managers':['HR Manager'],'Data Analyst':['BI Analyst'],'Chartered Accountant':['CA'],'Cybersecurity Analyst':['InfoSec Analyst'],'Machine Learning Engineer':['ML Engineer']}.items():
 tid=seen.get(title.lower())
 if tid:
  for alias in aliases:data['resume_title_aliases'].append({'title_id':tid,'alias':alias,'normalized_alias':alias.lower()})
data['resume_title_aliases']=list({(a['title_id'],a['normalized_alias']):a for a in data['resume_title_aliases']}.values())
out.write_text(json.dumps(data,separators=(',',':')))
print({k:len(v) for k,v in data.items()})
